void shadowRendering(HSD_Shadow *shadow, s32 index)
{
    HSD_LObj *light;
    Vec3 interest;
    HSD_ViewingRect rect;
    Vec3 eye;
    Vec3 up;
    Vec3 position;
    f32 size = 10.0f;
    f32 radius = 80.0f;
    f32 radians = (f32)DEG2RAD_D(45.0);

    if (shadow == 0) {
        OSReport("error!! shadow is NULL  zdNum=%d \n", index);
        return;
    }
    if (camTmp == 0) {
        OSReport("camTmp is NULL \n");
        return;
    }
    light = (HSD_LObj *)HSD_ShadowGetUserData(shadow);
    if (light == 0) {
        OSReport("lobj NULL\n");
        return;
    }
    if (light->flags & LOBJ_HIDDEN)
        return;
    shadowSetZoid(shadow, index);
    interest.x = camTmp->eye.x;
    interest.y = camTmp->eye.y;
    interest.z = camTmp->eye.z;
    position.x = camTmp->eye.x;
    position.y = 800.0f + camTmp->eye.y;
    position.z = camTmp->eye.z;
    if (shadow->camera == 0) {
        OSReport("shadow->camera is NULL \n");
        return;
    }
    HSD_CObjSetInterest(shadow->camera, &interest);
    HSD_CObjSetEyePosition(shadow->camera, &position);
    HSD_CObjGetEyePosition(shadow->camera, &eye);
    HSD_CObjGetUpVector(shadow->camera, &up);
    HSD_ViewingRectInit(&rect, &eye, &interest, &up,
                       (light->flags & (u32)LOBJ_TYPE_MASK) == (u32)LOBJ_INFINITE ? 0 : 1);
    HSD_ViewingRectAddRect(&rect, &interest, size, -size, -size, size);
    eye.x = interest.x + radius * wsinf(camTmp->yaw);
    eye.y = interest.y;
    eye.z = interest.z + radius * wcosf(camTmp->yaw);
    HSD_ViewingRectAddRect(&rect, &eye, size, -size, -size, size);
    eye.x = interest.x + radius * wsinf(camTmp->yaw + radians);
    eye.y = interest.y;
    eye.z = interest.z + radius * wcosf(camTmp->yaw + radians);
    HSD_ViewingRectAddRect(&rect, &eye, size, -size, -size, size);
    eye.x = interest.x + radius * wsinf(camTmp->yaw - radians);
    eye.y = interest.y;
    eye.z = interest.z + radius * wcosf(camTmp->yaw - radians);
    HSD_ViewingRectAddRect(&rect, &eye, size, -size, -size, size);
    if (HSD_ViewingRectCheck(&rect) != 0)
        HSD_ShadowSetViewingRect(shadow, rect.top, rect.bottom, rect.left, rect.right);
    else
        HSD_ShadowSetViewingRect(shadow, size, -size, -size, size);
    HSD_ShadowSetIntensity(shadow, 128);
    HSD_StartRender(HSD_RP_OFFSCREEN);
    HSD_ShadowInit(shadow);
    HSD_ShadowStartRender(shadow);
    HSD_ShadowEndRender(shadow);
    HSD_EndRender();
}
