s32 TEA_mcChkSlotZoid(s32 slot)
{
    s32 a = 4;
    s32 b = 8;
    s32 c = 0;
    s32 err = 0;
    s64 limit;

    limit = OSGetTime() / (OS_BUS_CLOCK / 4) + 20;
    if (TEA_mcChkSlotVs(slot) == 0) {
        return 0;
    }
    if (TEA_mcChkSector(slot) == 0) {
        puts("SLOT ZOIDCHK BAD 8192 ");
        TEA_mcMsg(slot, slot + 0x6c);
        return 0;
    }
    while (1) {
        if (slot == 0) {
            err = CARDMount(0, CardWorkArea, TEA_mcCardEject);
        } else {
            err = CARDMount(1, CardWorkArea2, TEA_mcCardEject);
        }
        if (err != -1) {
            break;
        }
        if (OSGetTime() / (OS_BUS_CLOCK / 4) > limit) {
            return 0;
        }
    }
    MemCardStatus[slot] = err;
    switch (err) {
    case -6:
    case -13:
        CARDUnmount(slot);
    case -128:
    case -5:
    case -3:
    case -2:
        MemCardOn[slot] = 0;
        MemCardStatus[slot] = err;
        puts("SLOT ZOIDCHK BAD CARD ");
        TEA_mcMsg(slot, slot + 0x6c);
        return 0;
    }
    OSReport("SLOT ZOIDCHK\tMount OK %d \n", err);
    MemCardOn[slot] = 1;
    strcpy(menusaveloadfilename, MC_FILENAME_MSG);
    if (TEA_mcFileExist(slot, menusaveloadfilename) == 0) {
        CARDUnmount(slot);
        MemCardStatus[slot] = -2;
        puts("SLOT ZOIDCHK NO DATA ");
        if (slot == 0) {
            TEA_mcMsg(slot, 0x71);
        } else {
            TEA_mcMsg(slot, 0x6b);
        }
        return 0;
    }
    CARDUnmount(slot);
    return 1;
}
