s32 TEA_mcChkSlotNoChk(s32 slot)
{
    s32 memsize = 4;
    s32 sector = 8;
    s32 unused = 0;
    s32 err = 0;
    s64 limit;

    limit = OSGetTime() / (__OSBusClock / 4) + 30;
    MemcardNowSlot = slot;
    {
        s32 n = 0;
        puts("SLOT CHK 0");
        while (1) {
            err = CARDProbeEx(slot, &memsize, &sector);
            if (err == 0) {
                MemCardSectorSize = sector;
                CARDFreeBlocks(slot, &MemCardFreeSize, &MemCardFreeDir);
                MemCardStatus[slot] = 0;
                MemCardOn[slot] = 1;
                return 1;
            }
            if (err == -2) {
                TEA_mcError(slot, err);
                MemCardStatus[slot] = err;
                return 1;
            }
            if (err == -3) {
                MemCardOn[slot] = 0;
                MemCardStatus[slot] = err;
                puts("NO CARD ");
                return 0;
            }
            if (OSGetTime() / (__OSBusClock / 4) > limit) {
                MemCardStatus[slot] = -128;
                return 0;
            }
            if (err == -128) {
                puts("CARD FATAL ERROR B");
                if (TEA_mcChkSlotEx(slot) == 1) {
                    puts("CARD SLOT CHK EX OK");
                    return 1;
                }
                n++;
                CARDUnmount(slot);
                if (n > 10) {
                    n = 0;
                    CARDInit();
                }
            }
            if (err == -1) {
                continue;
            }
            if (err == 0) {
                continue;
            }
            MemCardOn[slot] = 0;
            MemCardStatus[slot] = err;
            return 0;
        }
    }
}
