s32 TEA_mcChkSlotVs(s32 slot)
{
    s32 memsize = 4;
    s32 sector = 8;
    s32 unused = 0;
    s32 result = 0;
    s64 limit;
    limit = OSGetTime() / (__OSBusClock / 4) + 10;
    MemcardNowSlot = slot;
    while (1) {
        result = CARDProbeEx(slot, &memsize, &sector);
        if (result == -1) {
            if (OSGetTime() / (__OSBusClock / 4) > limit) return 0;
            MemCardStatus[slot] = 0;
            continue;
        }
        if (result == 0) {
            MemCardSectorSize = sector;
            CARDFreeBlocks(slot, &MemCardFreeSize, &MemCardFreeDir);
            MemCardStatus[slot] = 0;
            MemCardOn[slot] = 1;
            puts("VS.ON CARD ");
            return 1;
        }
        if (result == -3) {
            MemCardOn[slot] = 0;
            MemCardStatus[slot] = result;
            puts("VS..NO CARD ");
            TEA_mcMsg(slot, slot + 0x47c);
            return 0;
        }
        switch (result) {
        case -2: case -6: case -5: case -13:
            MemCardOn[slot] = 0;
            MemCardStatus[slot] = result;
            puts("VS.BAD CARD ");
            TEA_mcMsg(slot, slot + 0x6c);
            return 0;
        }
        OSReport("VS.MemCard%d \x82\xc8\x82\xb5 \n", slot);
        MemCardStatus[slot] = result;
        MemCardOn[slot] = 0;
        return 0;
    }
}
