s32 TEA_mcMount(s32 slot)
{
    s32 a = 4;
    s32 b = 8;
    s32 c = 0;
    s32 err = 0;
    s64 limit;

    limit = OSGetTime() / (OS_BUS_CLOCK / 4) + 10;
    MemcardNowSlot = slot;
    if (MemCardOn[slot] == 1) {
        OSReport("MemCard Mount \x8d\xcf\n");
        CARDUnmount(1);
        CARDUnmount(0);
    }
    OSReport("MemCard Mount set \n");
    if (slot == 0) {
        CARDMountAsync(0, CardWorkArea, TEA_mcCardEject, 0);
    } else {
        CARDMountAsync(1, CardWorkArea2, TEA_mcCardEject, 0);
    }
    while ((err = CARDGetResultCode(slot)) == -1) {
        if (OSGetTime() / (OS_BUS_CLOCK / 4) > limit) {
            return 0;
        }
    }
    MemCardStatus[slot] = err;
    switch (err) {
    case -13:
        TEA_mcBadEncFormatEnc(slot);
        return 0;
    case -3:
        return 0;
    case -6:
    case 0:
        MemCardError = 0;
        OSReport("MemCard Mount Ok :");
        err = CARDCheckAsync(slot, 0);
        if (err == -13) {
            return TEA_mcSetEnc(slot);
        }
        if (err < 0) {
            OSReport("\t\x8f" "C\x95\x9c" "1\x8e\xb8\x94s. (%d)\n", err);
            if (TEA_mcError(slot, err) == 1) {
                TEA_mcSetEnc(slot);
                OSReport("\tCardUnMount. (%d)\n", err);
                CARDUnmount(slot);
                return 0;
            }
            CARDUnmount(slot);
            return 0;
        }
        OSReport("\t\x8f" "C\x95\x9c Ok \n");
        MemCardError = 0;
        MemCardOn[slot] = 1;
        return 1;
    case -5:
    case -2:
        TEA_mcResult(err);
        TEA_mcError(slot, err);
        return 0;
    }
    OSReport("\tMount %d \n", err);
    OSReport("MemCard Mount End \n");
    err = err;
    return 1;
}
