s32 TEA_mcFileWrite(s32 slot, void *buf, s32 len)
{
    s32 err = 0;
    s32 x0 = 0;
    s32 x1 = 0;
    s32 x2 = 0;
    u32 alen;
    s64 limit;

    alen = (len + MemCardSectorSize - 1) & ~(MemCardSectorSize - 1);
    limit = OSGetTime() / (OS_BUS_CLOCK / 4) + 60;
    MemcardNowSlot = slot;
    OSReport("CARDWrite %dByte SaveSize=%d \n", len, alen);
    x2 = x1 = x0 = CARDGetXferredBytes(slot);
    err = CARDWriteAsync(&MemCardFileInfo, buf, alen, 0, 0);
    TEA_mcResult(err);
    if (err < -1) {
        TEA_mcError(slot, err);
        OSReport("failedwrite_a. (%d)\n", err);
        return 0;
    }
    while ((err = CARDGetResultCode(slot)) == -1) {
        x1 = CARDGetXferredBytes(slot);
        if (x1 != x2) {
            OSReport("\tWriteByte(%8d)\n", x1 - x0);
            x2 = x1;
        }
        if (OSGetTime() / (OS_BUS_CLOCK / 4) > limit) {
            MemCardStatus[slot] = -128;
            return 0;
        }
        if (MemCardOn[slot] == 0) {
            return 0;
        }
    }
    if (err < -1) {
        OSReport("failedwrite_b. (%d)\n", err);
        return 0;
    }
    OSReport("done. (%d)\n", err);
    if (MemCardOn[slot] == 0) {
        return 0;
    }
    return 1;
}
