void TEA_usbmccControlChk(u8 code)
{
    OSReport("mcc\x83R\x83\x93\x83g\x83\x8d\x81[\x83\x8b\x83R\x81[\x83h\x8e\xf3\x90M\n");
    switch (code) {
    case 1:
        tea_usbsend.flag = 0;
        tea_usbrecv.flag = 1;
        tea_usbrecv.api = 0;
        tea_usbrecv.sub = 0;
        tea_usbrecv.size = 0;
        tea_usbrecv.done = 0;
        OSReport("Recive 1stProc\x8fI\x97\xb9\n");
        hioReady = 0;
        hioBusy = 1;
        break;
    case 0xff:
        usbbufRead(&tea_usbrecv.api, 0, 2);
        usbbufRead(&tea_usbrecv.sub, 2, 2);
        usbbufRead(&tea_usbrecv.size, 4, 4);
        tea_usbrecv.ptr = (u8 *)hioRecvBuf + 8;
        memcpy(tea_usbrecv.data, tea_usbrecv.ptr, 20);
        OSReport(" ApiCodex=%04X SubCode=%04X Size=%8X \n", tea_usbrecv.api, tea_usbrecv.sub, tea_usbrecv.size);
        OSReport(" ApiCoded=%04d SubCode=%04d Size=%8d \n", tea_usbrecv.api, tea_usbrecv.sub, tea_usbrecv.size);
        tea_usbrecv.done = 1;
        OSReport("\x8fI\x97\xb9\x83R\x81[\x83h\x8am\x94" "F\n");
        hioReady = 1;
        hioBusy = 0;
        break;
    }
    code = 0;
}
