s32 TEA_BgmSfxLoad(char *name, u16 id)
{
    s16 result = 0;
    s32 loaded = 0;

    loaded = TeaSoundSfxLoadNum;
    if (TeaSeqPlayFlag == 1) {
        TEA_AudioSeqStop();
        TEA_AudioSeqFree();
        TeaSeqPlayFlag = 0;
    }
    if (loaded == 0) {
        sReadPre();
        TEA_SoundSfxLoad(lit_1859, 8);
        loaded++;
    }
    if (loaded == 1) {
        sReadPre();
        return TEA_SoundSfxLoad(name, (u16)id);
    } else if (loaded > 1) {
        sReadPre();
        TEA_SoundSfxPop();
        sReadPre();
        return TEA_SoundSfxLoad(name, (u16)id);
    }
    TeaSoundSfxLoadNum = loaded;
    return 1;
}
s32 TEA_SoundSfxLoad(char *name, s16 id)
{
    char path[80];

    sReadPre();
    sprintf(path, "%s.sam", name);
    OSReport("sound SFX load [%s] \n", path);
    if (fexist(path) == 0) {
        return 0;
    }
    if (sFileLenAlloc(path) == 0) {
        OSReport("sam  out of memory %s\n", path);
        return 0;
    }
    if (HSD_AudioSFXLoad(name, id) == 1) {
        if (HSD_AudioSFXLoadCheck() == 0) {
            sReadPre();
        }
        strcpy(TeaSfxNamePush[TeaSoundSfxLoadNum].name, name);
        TeaSfxNamePush[TeaSoundSfxLoadNum].id = id;
        TeaSfxNamePush[TeaSoundSfxLoadNum].flag = 1;
        TeaSoundSfxLoadNum++;
        TeaSfxNamePush[TeaSoundSfxLoadNum].flag = 0;
        OSReport("SE Load Num=%d fn=%s\n", TeaSoundSfxLoadNum, path);
    }
    return 1;
}
