s32 TEA_SeOnF(u16 id, f32 vol_in, f32 pan_in)
{
    s32 i = 0;
    u8 pan;
    u8 vol;
    u32 voice;

    if (id == -1) {
        return -1;
    }
    TEA_SePanVol(vol_in, pan_in, &pan, &vol);
    voice = HSD_AudioSFXStart(id, vol, pan);
    if (voice == 0xFFFFFFFF) {
        TEA_VoiceNumChk();
        return -1;
    }
    TEA_VoiceNumChk();
    for (i = 0; i < 64; i++) {
        if (TeaVoiceFlag[i] == 0) {
            TeaVoiceId[i] = voice;
            TeaVoiceFlag[i] = 1;
            TeaVoiceNum++;
            return voice;
        }
    }
    return -1;
}
u8 TEA_VoiceNumChk(void)
{
    s32 i = 0;
    s32 count = 0;
    s32 id;
    u32 result;

    for (i = 0; i < 64; i++) {
        if (TeaVoiceFlag[i] != 0) {
            id = TeaVoiceId[i];
            result = sndFXCheck(id);
            if (result == 0xFFFFFFFF) {
                TeaVoiceId[i] = id;
                TeaVoiceFlag[i] = 0;
            } else {
                count++;
            }
        }
    }
    TeaVoiceNum = count;
    return count;
}
void TEA_VoiceOn(u8 character, s16 voice)
{
    char path[80];
    sReadPre();
    sprintf(path, "voice/%02d/V%02d_%02d.adp", character, character, voice);
    if (fexist(path))
        TEA_VoiceFilePlay(path, TEA_VOICEVOL, 0);
    OSReport("voice [%s] start \n", path);
}
