void TeaBgm(s16 no)
{
    char path[80];
    s32 flag = 1;

    if (no == -1) {
        TEA_AudioSeqStop();
        TEA_AudioSeqFree();
        TEA_BGMNO = -1;
        TeaSeqPlayFlag = 0;
        return;
    }
    if (TEA_BGMNO == no) {
        return;
    }
    if (TEA_BGMNO != -1) {
        TEA_AudioSeqStop();
        OSReport("SEQ StopSeq \n");
        TEA_AudioSeqFree();
        OSReport("SEQ Free \n");
        TeaSeqPlayFlag = 0;
    }
    TEA_BGMNO = no;
    sprintf(path, "audio/bgm/%s.son", ((TeaSoundEnt *)TeaSound)[no].name);
    OSReport("SEQ Play FileChk %s \n", path);
    sReadPre();
    if (fexist(path) == 0) {
        TEA_AudioSeqStop();
        TEA_AudioSeqFree();
        TEA_BGMNO = -1;
        TeaSeqPlayFlag = 0;
        return;
    }
    sReadPre();
    sprintf(path, "audio/bgm/%s", ((TeaSoundEnt *)TeaSound)[no].name);
    if (TEA_BgmSfxLoad(path, ((TeaSoundEnt *)TeaSound)[no].a) == 0) {
        OSReport("%s error \n", path);
        return;
    }
    OSReport("SEQ LoadSfxOk \n");
    sReadPre();
    sprintf(path, "audio/bgm/%s.son", ((TeaSoundEnt *)TeaSound)[no].name);
    TEA_SeqPlay(((TeaSoundEnt *)TeaSound)[no].a, ((TeaSoundEnt *)TeaSound)[no].b, path);
    OSReport("SEQ PlayOk %s \n", path);
    no = no;
    flag = 0;
}
