void TEA_SeqPlay(u16 a, u16 b, char *name)
{
    u16 c = 300;
    u32 seq;

    if (TeaSeqPlayFlag == 1) {
        OSReport("SEQ STOP %s\n", name);
        TEA_AudioSeqStop();
        TEA_AudioSeqFree();
        TeaSeqPlayFlag = 0;
    }
    if (name == (char *)0) {
        TEA_BGMNO = -1;
        return;
    }
    if (*name == 0) {
        TEA_BGMNO = -1;
        return;
    }
    sReadPre();
    seq = HSD_AudioSeqPlay(a, b, name, 0);
    OSReport("SEQ PLAY OK VOLSET(%d)  %d\n", TEA_BGMVOL, seq);
    if (seq == 0xFFFFFFFF) {
        TEA_BGMNO = -1;
        TeaSeqPlayFlag = 0;
        return;
    }
    while (HSD_AudioSeqPlayCheck() == 1) {
        sReadPre();
    }
    seq = HSD_AudioSeqPlayGetSeqId();
    OSReport("AUDIO -----%d \n", seq);
    TeaSeqPlayFlag = 1;
    TeaSeqId = seq;
    TEA_AudioSeqVolume(TEA_BGMVOL, 0, 0);
    OSReport("SEQ PLAY %s\n", name);
}
